struct ContainmentRule: DisambiguationRule {
    var isHardConstraint: Bool { true }
    /// One entry per annotation; the containers inside an entry are alternatives.
    let groups: [[() -> Set<BinarySpan>]]
    let negated: Bool
    func prune(_ yields: inout Set<BinarySpan>) -> Int {
        let gys = groups .map { $0.map { $0() } }
        var pruned = 0
        for span in yields {
            // Every group must contain the span in at least one of its containers.
            let contained = gys.allSatisfy { group in
                group.contains
{ cy in cy.contains { $0.i <= span.i && span.j <= $0.j } }
            }
            if contained == negated { yields.remove(span); pruned += 1 }   // confinedTo prunes ¬contained; excludedFrom prunes contained
        }
        return pruned
    }
}
extension Parser {
  mutating func loadCurrentSyntaxNodeFromCache(for kind: SyntaxKind) -> Syntax? {
    guard parseLookup != nil else {
      return nil
    }

    let currentOffset = self.lexemes.offsetToStart(self.currentToken)
    if let node = parseLookup!.lookUp(AbsolutePosition(utf8Offset: currentOffset), kind: kind) {
      self.lexemes.advance(by: node.totalLength.utf8Length, currentToken: &self.currentToken)
      return node
    }

    return nil
  }

  mutating func registerNodeForIncrementalParse(node: RawSyntax, startToken: Lexer.Lexeme) {
    lookaheadRanges.registerNodeForIncrementalParse(
      node: node,
      lookaheadLength: lexemes.lookaheadTracker.pointee.furthestOffset - self.lexemes.offsetToStart(startToken)
    )
  }
}
}

