extension Parser.Lookahead{
  func canParseArgumentLabelList() -> Bool {
    var lookahead = self.lookahead()
    guard lookahead.consume(if: .leftParen) != nil else {
      return false
    }

    var loopProgress = LoopProgressCondition()
    while !lookahead.at(.endOfFile, .rightParen) && lookahead.hasProgressed(&loopProgress) {
      // Check to see if there is an argument label.
      guard lookahead.atArgumentLabel() && lookahead.peek().rawTokenKind == .colon else {
        return false
      }

      lookahead.consumeAnyToken()
      guard lookahead.consume(if: .colon) != nil else {
        return false
      }
    }

    guard lookahead.consume(if: .rightParen) != nil else {
      return false
    }

    return true
  }
}
public func findCommonAncestorOrSelf(_ lhs: Syntax, _ rhs: Syntax) -> Syntax? {
  var lhs: Syntax? = lhs
  var rhs: Syntax? = rhs
  while lhs != nil && rhs != nil {
    if lhs == rhs {
      return lhs
    }
    if let lhsUnwrapped = lhs, let rhsUnwrapped = rhs {
      if lhsUnwrapped.id < rhsUnwrapped.id {
        rhs = rhsUnwrapped.parent
      } else {
        lhs = lhsUnwrapped.parent
      }
    }
  }
  return nil
}
}

